SLUG, NAME, CHNO = "Probability", "Probability", 7

def pr(fr): return f"${fx(Fr(fr))}$"
def pwrongs(p):
    p = Fr(p); n, d = p.numerator, p.denominator; out = []
    for c in (1 - p, Fr(n + 1, d), Fr(n, d + 1), Fr(n - 1, d) if n > 1 else None, p / 2, Fr(n + 1, d + 1), Fr(d - 1, d + 2)):
        if c is not None and c != p and 0 < c < 1 and pr(c) not in out: out.append(pr(c))
    return out
def pq(q, p, why=""):
    return M4(q, pr(p), pwrongs(p), why)
def pq01(q, p, why=""):
    """MCQ whose answer is exactly 0 or 1."""
    c = "$0$" if p == 0 else "$1$"
    return M4(q, c, ["$\\frac12$", "$\\frac{1}{6}$", "$-1$" if p == 0 else "$2$"], why)

DIE = {"an even number": lambda n: n % 2 == 0, "an odd number": lambda n: n % 2 == 1, "a prime number": lambda n: n in (2, 3, 5), "a number greater than 4": lambda n: n > 4,
       "a number less than 3": lambda n: n < 3, "a multiple of 3": lambda n: n % 3 == 0, "the number 5": lambda n: n == 5, "a factor of 6": lambda n: n in (1, 2, 3, 6),
       "a perfect square": lambda n: n in (1, 4), "a number not divisible by 3": lambda n: n % 3 != 0, "a number at least 5": lambda n: n >= 5, "a number at most 2": lambda n: n <= 2,
       "a composite number": lambda n: n in (4, 6), "a number between 2 and 5": lambda n: 2 < n < 5}
def die_p(name): return Fr(sum(1 for n in range(1, 7) if DIE[name](n)), 6)
def dice2(pred): return Fr(sum(1 for a, b in product(range(1, 7), repeat=2) if pred(a, b)), 36)
def coins(k, pred): return Fr(sum(1 for t in product("HT", repeat=k) if pred(t)), 2 ** k)
def word_p(word, pred): c = Counter(word); return Fr(sum(v for k, v in c.items() if pred(k)), len(word))
